INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'misterio-en-la-caja-secreta', 'Misterio en la Caja Secreta', 'Dinámica de creación táctil y misterio a ciegas donde los scouts construyen una escultura con las manos dentro de una caja secreta.', '<h2>📜 Descripción de Misterio en la Caja Secreta</h2>
<p><b>Misterio en la Caja Secreta</b> es una dinámica de artesanía háptica, percepción táctil a ciegas y trabajo en equipo a oscuras. Organizados por patrullas, los scouts reciben una caja misteriosa con orificios laterales para introducir únicamente las manos. En su interior se encuentra un lote heterogéneo de materiales de manualidades (ej. <i>caja de cartón, arcilla, limpiapipas y palitos de helado</i>).</p>
<p>Sin poder mirar en ningún momento hacia el interior del recipiente, dos integrantes de la patrulla meten sus manos y colaboran a ciegas para moldear y ensamblar una escultura u objeto representativo del campamento (ej. <i>''Un tótem scout''</i>, <i>''Una carpa canadiense''</i> o <i>''Una brújula de patrulla''</i>). El resto del equipo sigue el proceso desde afuera sin dar pistas visuales directas.</p>
<p>Esta actividad ejercita la motricidad fina en penumbra, la comunicación táctil, la imaginación espacial y la cooperación en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega Misterio en la Caja Secreta?</h2>
<p>Para llevar a cabo la dinámica con entusiasmo, sorpresa e ingenio, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Preparación de la Caja Secreta:</b> Se dispone de una caja cubierta con tela u orificios para insertar los brazos sin ver el interior.</li>
  <li><b>Asignación del Objeto a Crear:</b> Se entrega en secreto a los constructores el título del artefacto a modelar a ciegas.</li>
  <li><b>Fase de Ensamblaje Táctil:</b> Durante 5 minutos, los participantes moldean el objeto guiándose solo por el tacto.</li>
  <li><b>El Desenmascaramiento:</b> Se retira la cubierta de la caja para exhibir la obra ante las risas y sorpresas de la unidad.</li>
  <li><b>Adivinanza y Reflexión:</b> Las otras patrullas adivinan la escultura y se valora la capacidad de trabajo a ciegas.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de Misterio en la Caja Secreta</h2>
<p>La actividad valora el ingenio táctil y la precisión del ensamblaje en el Tally:</p>
<ul>
  <li><b>Mayor Fidelidad a Ciegas:</b> Otorgar 5 puntos a la patrulla cuyo objeto moldeado sin mirar resulte más reconocible.</li>
  <li><b>Coordinación Táctil en Pareja:</b> Otorgar 3 puntos a los constructores que mejor se entiendan con las manos dentro de la caja.</li>
  <li><b>Originalidad de los Materiales:</b> Otorgar 3 puntos al equipo que aproveche los elementos de forma más ingeniosa.</li>
</ul>', '/uploads/misterio-en-la-caja-secreta.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Caja de Cartón", "Arcilla", "Limpiapipas", "Palitos de Helado"], "objetivos": ["Estimular la creatividad", "Reforzar el desarrollo de los sentidos", "Desarrollar la motricidad", "Trabajo en equipo"], "justificacion_areas": "Misterio en la Caja Secreta potencia la creatividad al exigir la construcción espacial a ciegas confiando únicamente en la percepción táctil. Desarrolla la sociabilidad al afianzar el trabajo coordinado en pareja, la comunicación a ciegas y el apoyo entre pares desde Manada hasta Clan.", "variaciones": "<b>Creación a Ciegas con Venda en los Ojos:</b> Realizar el modelado sobre la mesa con vendaje visual directo.<br><b>Escultura Secreta en Silencio:</b> Construir el objeto a ciegas sin emitir una sola palabra.<br><b>Relevo de Constructores:</b> Cambiar de pareja cada 60 segundos dentro de la caja.", "recomendaciones": "Asegurar que los materiales dentro de la caja sean limpios y seguros. Estimular la risa sana y la sorpresa.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Participando con entusiasmo en la creación de la escultura secreta a ciegas."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando la prohibición de mirar dentro de la caja y los tiempos asignados."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando ideas a través de formas táctiles en la arcilla."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Colaborando alegremente en la seisena durante la revelación del objeto."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Liderando construcciones táctiles expresivas en la patrulla."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo la colaboración respetuosa entre las integrantes a ciegas."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando la tridimensionalidad del objeto desde la percepción háptica."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo el apoyo mutuo y la inclusión en el trabajo a ciegas."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Aportando creatividad manual en los desafíos de ensamble táctil."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando disciplina y juego limpio durante la inmovilidad visual."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Diseñando figuras complejas usando el sentido del tacto."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la fraternidad y confianza en el equipo de Tropa."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "unidad": "Avanzada", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "como_se_cumple": "Compartiendo creaciones tridimensionales e interpretación háptica en Avanzada."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Promoviendo la inclusión sensorial y el trabajo cooperativo."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Fomentando el arte táctil y la hermandad alegre en el Clan Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Viviendo la fraternidad scout y la ayuda mutua a ciegas."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

